package main

import (
	"fmt"
	"net/url"
)

func main() {
	myURL := "https://www.example.com/path?query=123#fragment"
	println("URL:", myURL)
	fmt.Printf("type : %T\n", myURL)

	// change type to *URL

	parsedURL, err := url.Parse(myURL)
	if err != nil {
		fmt.Printf("error while parsing URL: %v", err)
		return
	}
	fmt.Printf("Parsed URL: %+v\n", parsedURL)
	fmt.Println("Scheme:", parsedURL.Scheme)
	fmt.Println("Host:", parsedURL.Host)
	fmt.Println("Path:", parsedURL.Path)
	fmt.Println("RawQuery:", parsedURL.RawQuery)
	fmt.Println("Fragment:", parsedURL.Fragment)

	// Modify the URL
	parsedURL.Path = "/newpath"
	parsedURL.RawQuery = "query=456"
	parsedURL.Fragment = "newfragment"

	newURL := parsedURL.String()
	fmt.Println("Modified URL:", newURL)
}

// Output
// URL: https://www.example.com/path?query=123#fragment
// type : string
// Parsed URL: https://www.example.com/path?query=123#fragment
// Scheme: https
// Host: www.example.com
// Path: /path
// RawQuery: query=123
// Fragment: fragment
// Modified URL: https://www.example.com/newpath?query=456#newfragment

package main

import (
	"encoding/json"
	"fmt"
)

type Person struct {
	Name   string `json:"name"`
	Age    int    `json:"age"`
	Gender string `json:"gender"`
}

func main() {
	person := Person{
		Name:   "John Doe",
		Age:    30,
		Gender: "Male",
	}
	fmt.Println("Person Data : ", person)

	// Marshelling (Encoding Go struct to JSON)
	jsonData, err := json.Marshal(person)
	if err != nil {
		fmt.Println("Error in Marshelling : ", err)
	}
	fmt.Println("JSON Data : ", string(jsonData))

	// Unmarshalling (Decoding JSON to Go struct)
	var person2 Person
	err = json.Unmarshal(jsonData, &person2)
	if err != nil {
		fmt.Println("Error in Unmarshalling : ", err)
	}
	fmt.Println("Unmarshalled Data : ", person2)
}

// Output
// Person Data :  {John Doe 30 Male}
// JSON Data :  {"name":"John Doe","age":30,"gender":"Male"}
// Unmarshalled Data :  {John Doe 30 Male}

